arguments.cmd:
apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/styles.css
+:root{
+  --bg:#0A0A0A;
+  --surface:#0F1012;
+  --surface-2:#121418;
+  --border:rgba(255,255,255,.10);
+  --text:#F4F6FA;
+  --muted:rgba(244,246,250,.72);
+  --muted-2:rgba(244,246,250,.56);
+
+  --accent:#2EB0FF;
+  --accent-2:#FFB02E;
+  --danger:#FF4D6D;
+  --ok:#38D98B;
+
+  --shadow:0 24px 80px rgba(0,0,0,.55);
+  --shadow-soft:0 18px 48px rgba(0,0,0,.38);
+  --ring:0 0 0 3px rgba(46,176,255,.25);
+
+  --radius-xl:24px;
+  --radius-lg:18px;
+  --radius-md:14px;
+  --radius-sm:12px;
+  --radius-xs:10px;
+
+  --container:1180px;
+  --gutter:clamp(18px, 4vw, 36px);
+  --section-pad:clamp(64px, 8vw, 120px);
+}
+
+*{box-sizing:border-box}
+html{color-scheme:dark}
+body{
+  margin:0;
+  font-family:Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
+  background:
+    radial-gradient(1100px 620px at 80% 0%, rgba(46,176,255,.12), transparent 55%),
+    radial-gradient(980px 540px at 10% 15%, rgba(255,176,46,.10), transparent 60%),
+    var(--bg);
+  color:var(--text);
+  line-height:1.55;
+}
+
+a{color:inherit}
+img{max-width:100%; display:block}
+.container{max-width:var(--container); margin:0 auto; padding:0 var(--gutter)}
+.sr-only{position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); border:0}
+
+:focus-visible{outline:none; box-shadow:var(--ring)}
+
+/* Top bar */
+.topbar{
+  position:sticky;
+  top:0;
+  z-index:1000;
+  backdrop-filter:saturate(160%) blur(14px);
+  background:rgba(10,10,10,.68);
+  border-bottom:1px solid rgba(255,255,255,.08);
+}
+.topbar__inner{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  padding:16px var(--gutter);
+  max-width:calc(var(--container) + var(--gutter)*2);
+  margin:0 auto;
+  gap:14px;
+}
+.brand{
+  display:flex;
+  align-items:center;
+  gap:12px;
+  text-decoration:none;
+  white-space:nowrap;
+}
+.brand__mark{
+  width:34px;
+  height:34px;
+  border-radius:12px;
+  background:
+    radial-gradient(80% 90% at 30% 20%, rgba(46,176,255,.95), rgba(46,176,255,.12) 55%, rgba(46,176,255,0) 70%),
+    radial-gradient(90% 80% at 70% 70%, rgba(255,176,46,.85), rgba(255,176,46,.10) 55%, rgba(255,176,46,0) 72%),
+    rgba(255,255,255,.06);
+  border:1px solid rgba(255,255,255,.12);
+  box-shadow:0 18px 44px rgba(0,0,0,.55);
+}
+.brand__text{display:flex; flex-direction:column; gap:1px}
+.brand__name{font-weight:700; letter-spacing:-.02em}
+.brand__tag{font-size:12px; color:var(--muted-2)}
+
+.nav{
+  display:flex;
+  align-items:center;
+  gap:12px;
+}
+.nav__links{
+  display:flex;
+  align-items:center;
+  gap:8px;
+}
+.nav__link{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  padding:10px 12px;
+  border-radius:12px;
+  text-decoration:none;
+  color:var(--muted);
+  font-weight:500;
+  letter-spacing:-.01em;
+  transition:background .18s ease, color .18s ease;
+}
+.nav__link:hover{background:rgba(255,255,255,.06); color:var(--text)}
+.nav__link[aria-current="true"]{background:rgba(46,176,255,.10); color:var(--text); border:1px solid rgba(46,176,255,.18)}
+
+.nav__actions{display:flex; align-items:center; gap:10px}
+.btn{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap:10px;
+  padding:12px 14px;
+  border-radius:14px;
+  border:1px solid var(--border);
+  background:rgba(255,255,255,.04);
+  color:var(--text);
+  text-decoration:none;
+  font-weight:600;
+  letter-spacing:-.01em;
+  cursor:pointer;
+  transition:transform .16s ease, background .16s ease, border-color .16s ease;
+}
+.btn:hover{background:rgba(255,255,255,.07); transform:translateY(-1px)}
+.btn:active{transform:translateY(0)}
+.btn--primary{
+  background:linear-gradient(135deg, rgba(46,176,255,.95), rgba(46,176,255,.35));
+  border-color:rgba(46,176,255,.45);
+  box-shadow:0 18px 44px rgba(46,176,255,.12);
+}
+.btn--primary:hover{background:linear-gradient(135deg, rgba(46,176,255,1), rgba(46,176,255,.45))}
+.btn--quiet{background:transparent}
+.btn--quiet:hover{background:rgba(255,255,255,.06)}
+.icon{
+  width:18px;
+  height:18px;
+  fill:none;
+  stroke:currentColor;
+  stroke-width:1.8;
+  stroke-linecap:round;
+  stroke-linejoin:round;
+}
+
+.menu-btn{display:none}
+
+/* Language */
+.dropdown{position:relative}
+.dropdown__panel{
+  position:absolute;
+  top:calc(100% + 12px);
+  right:0;
+  width:min(280px, calc(100vw - 24px));
+  background:rgba(16,18,22,.92);
+  border:1px solid rgba(255,255,255,.12);
+  border-radius:16px;
+  box-shadow:var(--shadow-soft);
+  padding:10px;
+  display:none;
+}
+.dropdown[aria-expanded="true"] .dropdown__panel{display:block}
+.dropdown__item{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:10px;
+  padding:12px 12px;
+  border-radius:14px;
+  border:1px solid transparent;
+  background:transparent;
+  color:var(--text);
+  width:100%;
+  cursor:pointer;
+  text-align:left;
+}
+.dropdown__item:hover{background:rgba(255,255,255,.06); border-color:rgba(255,255,255,.10)}
+.dropdown__meta{font-size:12px; color:var(--muted-2)}
+
+/* Hero */
+.hero{padding:var(--section-pad) 0 40px; position:relative}
+.hero__grid{display:grid; grid-template-columns:1.15fr .85fr; gap:26px; align-items:stretch}
+.kicker{color:var(--muted-2); font-weight:600; letter-spacing:.12em; text-transform:uppercase; font-size:12px}
+.hero h1{margin:12px 0 12px; font-size:clamp(40px, 5vw, 64px); line-height:1.02; letter-spacing:-.04em}
+.lede{color:var(--muted); font-size:18px; max-width:60ch}
+.hero__actions{display:flex; gap:12px; margin-top:22px; flex-wrap:wrap}
+.hero__panel{
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(255,255,255,.12);
+  background:linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.02));
+  box-shadow:var(--shadow);
+  overflow:hidden;
+  min-height:420px;
+  display:flex;
+  flex-direction:column;
+}
+.carousel{display:flex; flex-direction:column; height:100%}
+.carousel__viewport{
+  position:relative;
+  flex:1;
+  overflow:hidden;
+}
+.carousel__track{
+  display:flex;
+  height:100%;
+  transition:transform 520ms cubic-bezier(.2,.8,.2,1);
+  will-change:transform;
+}
+.slide{
+  min-width:100%;
+  height:100%;
+  position:relative;
+}
+.slide__bg{
+  position:absolute;
+  inset:0;
+  background-size:cover;
+  background-position:center;
+  filter:saturate(.9) contrast(1.05);
+  transform:scale(1.04);
+}
+.slide__overlay{
+  position:absolute;
+  inset:0;
+  background:
+    linear-gradient(180deg, rgba(10,10,10,.25) 0%, rgba(10,10,10,.85) 65%, rgba(10,10,10,.95) 100%),
+    radial-gradient(620px 420px at 20% 10%, rgba(46,176,255,.18), transparent 55%);
+}
+.slide__content{
+  position:relative;
+  height:100%;
+  padding:26px 22px;
+  display:flex;
+  flex-direction:column;
+  justify-content:flex-end;
+  gap:10px;
+}
+.card-eyebrow{font-size:12px; letter-spacing:.12em; text-transform:uppercase; color:rgba(244,246,250,.72); font-weight:700}
+.slide__title{margin:0; font-size:24px; letter-spacing:-.03em; line-height:1.12}
+.slide__desc{margin:0; color:var(--muted); font-size:14px}
+.slide__cta{margin-top:10px; align-self:flex-start}
+
+.carousel__controls{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:10px;
+  padding:14px 16px;
+  border-top:1px solid rgba(255,255,255,.08);
+  background:rgba(10,10,10,.25);
+}
+.dots{display:flex; gap:8px; align-items:center}
+.dot{
+  width:8px;
+  height:8px;
+  border-radius:99px;
+  border:1px solid rgba(255,255,255,.18);
+  background:rgba(255,255,255,.06);
+  cursor:pointer;
+}
+.dot[aria-current="true"]{width:22px; background:rgba(46,176,255,.55); border-color:rgba(46,176,255,.55)}
+
+.control-group{display:flex; gap:10px; align-items:center}
+.icon-btn{
+  width:42px;
+  height:42px;
+  border-radius:14px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.04);
+  color:var(--text);
+  cursor:pointer;
+  display:grid;
+  place-items:center;
+  transition:background .16s ease, transform .16s ease;
+}
+.icon-btn:hover{background:rgba(255,255,255,.07); transform:translateY(-1px)}
+.icon-btn:active{transform:translateY(0)}
+
+.stat-stack{
+  display:grid;
+  grid-template-columns:1fr 1fr;
+  gap:14px;
+  margin-top:28px;
+}
+.stat{
+  border-radius:18px;
+  border:1px solid rgba(255,255,255,.10);
+  background:rgba(255,255,255,.03);
+  padding:16px;
+}
+.stat__value{font-size:22px; font-weight:800; letter-spacing:-.03em}
+.stat__label{color:var(--muted-2); font-size:12px; margin-top:4px}
+
+/* Sections */
+.section{padding:var(--section-pad) 0}
+.section__head{display:flex; align-items:flex-end; justify-content:space-between; gap:18px; margin-bottom:24px}
+.h2{margin:0; font-size:clamp(28px, 3vw, 40px); letter-spacing:-.04em; line-height:1.08}
+.sub{margin:10px 0 0; color:var(--muted); max-width:70ch}
+.section__title{max-width:76ch}
+
+.pill-row{display:flex; flex-wrap:wrap; gap:10px}
+.pill{
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.03);
+  border-radius:999px;
+  padding:10px 12px;
+  color:var(--muted);
+  font-weight:600;
+  cursor:pointer;
+  transition:background .16s ease, border-color .16s ease, color .16s ease;
+}
+.pill:hover{background:rgba(255,255,255,.06); color:var(--text)}
+.pill[aria-selected="true"]{background:rgba(46,176,255,.10); border-color:rgba(46,176,255,.22); color:var(--text)}
+
+/* Horizontal scrollers */
+.scroller{
+  position:relative;
+}
+.scroller__viewport{
+  overflow:auto;
+  scroll-snap-type:x mandatory;
+  -webkit-overflow-scrolling:touch;
+  scroll-behavior:smooth;
+  padding-bottom:6px;
+}
+.scroller__track{
+  display:flex;
+  gap:16px;
+  padding:4px 2px;
+}
+.scroller__viewport::-webkit-scrollbar{height:10px}
+.scroller__viewport::-webkit-scrollbar-track{background:transparent}
+.scroller__viewport::-webkit-scrollbar-thumb{background:rgba(255,255,255,.12); border-radius:999px}
+.scroller__viewport:focus-visible{box-shadow:var(--ring)}
+
+.scroller__controls{
+  display:flex;
+  gap:10px;
+  align-items:center;
+}
+
+.card{
+  scroll-snap-align:start;
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.03);
+  box-shadow:var(--shadow-soft);
+  overflow:hidden;
+  min-width:min(420px, 88vw);
+}
+.card__media{
+  aspect-ratio:16/10;
+  background:#0d0f14;
+  position:relative;
+}
+.card__media img{width:100%; height:100%; object-fit:cover; filter:saturate(.85) contrast(1.05)}
+.card__body{padding:18px 18px 18px}
+.card__kicker{color:var(--muted-2); font-weight:700; letter-spacing:.12em; text-transform:uppercase; font-size:12px}
+.card__title{margin:8px 0 10px; font-size:18px; letter-spacing:-.02em; line-height:1.2}
+.card__desc{margin:0; color:var(--muted); font-size:14px}
+.quote{
+  margin:14px 0 0;
+  padding-top:14px;
+  border-top:1px solid rgba(255,255,255,.10);
+  color:rgba(244,246,250,.82);
+  font-size:14px;
+}
+.quote footer{margin-top:10px; color:var(--muted-2); font-size:12px}
+
+/* Team */
+.team-card{
+  min-width:min(380px, 86vw);
+}
+.team-card .card__media{aspect-ratio:4/5}
+.team-card__top{
+  position:absolute;
+  inset:0;
+  background:
+    linear-gradient(180deg, rgba(10,10,10,.10) 0%, rgba(10,10,10,.65) 65%, rgba(10,10,10,.92) 100%);
+}
+.team-card__meta{
+  display:flex;
+  justify-content:space-between;
+  gap:10px;
+  color:rgba(244,246,250,.85);
+  font-size:12px;
+  letter-spacing:.08em;
+  text-transform:uppercase;
+  position:absolute;
+  left:16px;
+  right:16px;
+  top:14px;
+}
+.team-card__body{padding:18px}
+.team-name{margin:0; font-size:20px; letter-spacing:-.03em}
+.team-role{margin:6px 0 0; color:var(--muted); font-size:13px}
+.team-quote{margin:14px 0 0; color:rgba(244,246,250,.82); font-size:14px}
+.team-actions{margin-top:16px; display:flex; justify-content:space-between; align-items:center; gap:12px}
+.link{
+  color:rgba(46,176,255,.95);
+  text-decoration:none;
+  font-weight:700;
+}
+.link:hover{text-decoration:underline}
+.badge{
+  display:inline-flex;
+  align-items:center;
+  gap:8px;
+  border:1px solid rgba(255,255,255,.14);
+  padding:8px 10px;
+  border-radius:999px;
+  color:var(--muted);
+  font-weight:700;
+  font-size:12px;
+}
+
+/* CTA Banner */
+.cta{
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(255,255,255,.12);
+  background:
+    radial-gradient(900px 480px at 10% 10%, rgba(46,176,255,.20), transparent 60%),
+    radial-gradient(820px 420px at 80% 40%, rgba(255,176,46,.16), transparent 60%),
+    rgba(255,255,255,.03);
+  box-shadow:var(--shadow);
+  padding:clamp(22px, 4vw, 34px);
+  display:flex;
+  gap:18px;
+  align-items:center;
+  justify-content:space-between;
+}
+.cta__title{margin:0; font-size:28px; letter-spacing:-.03em}
+.cta__body{margin:8px 0 0; color:var(--muted); max-width:70ch}
+
+/* How we work */
+.two-col{display:grid; grid-template-columns:1.05fr .95fr; gap:22px; align-items:start}
+.panel{
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.03);
+  box-shadow:var(--shadow-soft);
+  padding:22px;
+}
+.panel h3{margin:0; font-size:20px; letter-spacing:-.02em}
+.panel p{color:var(--muted); margin:12px 0 0}
+.panel-list{margin:16px 0 0; padding:0; list-style:none; display:grid; gap:10px}
+.panel-list li{display:flex; gap:10px; color:rgba(244,246,250,.86)}
+.check{
+  width:18px;
+  height:18px;
+  border-radius:6px;
+  background:rgba(56,217,139,.16);
+  border:1px solid rgba(56,217,139,.28);
+  display:grid;
+  place-items:center;
+  flex:0 0 auto;
+  margin-top:2px;
+}
+.check svg{width:14px; height:14px}
+
+/* Insights grid */
+.grid{
+  display:grid;
+  grid-template-columns:repeat(3, minmax(0, 1fr));
+  gap:16px;
+}
+.mini{
+  border-radius:18px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.03);
+  overflow:hidden;
+  box-shadow:var(--shadow-soft);
+  min-height:100%;
+  display:flex;
+  flex-direction:column;
+}
+.mini__media{aspect-ratio:16/9; background:#0d0f14}
+.mini__media img{width:100%; height:100%; object-fit:cover; filter:saturate(.85) contrast(1.05)}
+.mini__body{padding:14px 14px 16px; display:flex; flex-direction:column; gap:10px; flex:1}
+.mini__top{display:flex; justify-content:space-between; gap:12px; align-items:center}
+.type{
+  font-size:12px;
+  letter-spacing:.12em;
+  text-transform:uppercase;
+  color:var(--muted-2);
+  font-weight:800;
+}
+.mini__title{margin:0; font-size:16px; letter-spacing:-.02em; line-height:1.22}
+.mini__footer{margin-top:auto; display:flex; justify-content:space-between; align-items:center; gap:12px}
+.chip{
+  border-radius:999px;
+  padding:8px 10px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.03);
+  color:var(--muted);
+  font-weight:700;
+  font-size:12px;
+}
+
+/* Principles */
+.principles{display:grid; grid-template-columns:repeat(4, minmax(0, 1fr)); gap:14px}
+.principle{
+  border-radius:20px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.03);
+  padding:18px;
+  box-shadow:var(--shadow-soft);
+}
+.principle h3{margin:0; letter-spacing:-.02em}
+.principle p{margin:10px 0 0; color:var(--muted); font-size:14px}
+
+/* Footer */
+footer{padding:56px 0 48px; border-top:1px solid rgba(255,255,255,.08)}
+.footer-top{display:grid; grid-template-columns:1fr 1fr; gap:16px}
+.footer-cta{
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.03);
+  padding:20px;
+  box-shadow:var(--shadow-soft);
+}
+.footer-cta h3{margin:0; letter-spacing:-.02em}
+.footer-cta p{margin:10px 0 0; color:var(--muted)}
+.footer-bottom{display:flex; flex-wrap:wrap; justify-content:space-between; gap:14px; margin-top:22px; color:var(--muted-2); font-size:12px}
+.footer-links{display:flex; flex-wrap:wrap; gap:10px}
+.footer-links a{color:var(--muted); text-decoration:none}
+.footer-links a:hover{text-decoration:underline; color:var(--text)}
+
+/* Cookie */
+.cookie{
+  position:fixed;
+  left:18px;
+  right:18px;
+  bottom:18px;
+  z-index:1200;
+  display:none;
+}
+.cookie[aria-hidden="false"]{display:block}
+.cookie__panel{
+  margin:0 auto;
+  max-width:940px;
+  border-radius:22px;
+  border:1px solid rgba(255,255,255,.14);
+  background:rgba(16,18,22,.92);
+  backdrop-filter: blur(14px) saturate(160%);
+  box-shadow:var(--shadow);
+  padding:18px;
+  display:flex;
+  gap:14px;
+  align-items:flex-start;
+  justify-content:space-between;
+}
+.cookie__text{max-width:70ch}
+.cookie__title{margin:0; font-weight:800; letter-spacing:-.02em}
+.cookie__desc{margin:8px 0 0; color:var(--muted); font-size:14px}
+.cookie__actions{display:flex; gap:10px; flex-wrap:wrap; justify-content:flex-end}
+.cookie__panel .btn{padding:10px 12px; border-radius:12px}
+.modal{
+  position:fixed;
+  inset:0;
+  z-index:1400;
+  display:none;
+}
+.modal[aria-hidden="false"]{display:block}
+.modal__backdrop{position:absolute; inset:0; background:rgba(0,0,0,.62)}
+.modal__dialog{
+  position:relative;
+  max-width:760px;
+  margin:6vh auto;
+  background:rgba(16,18,22,.96);
+  border:1px solid rgba(255,255,255,.14);
+  border-radius:24px;
+  box-shadow:var(--shadow);
+  padding:20px;
+}
+.modal__head{display:flex; justify-content:space-between; gap:12px; align-items:flex-start}
+.modal__head h3{margin:0; letter-spacing:-.02em}
+.modal__body{margin-top:12px; color:var(--muted)}
+.tog{
+  display:flex;
+  align-items:flex-start;
+  justify-content:space-between;
+  gap:14px;
+  padding:14px;
+  border-radius:18px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.03);
+  margin-top:12px;
+}
+.tog strong{color:var(--text)}
+.switch{
+  width:46px;
+  height:28px;
+  border-radius:999px;
+  border:1px solid rgba(255,255,255,.16);
+  background:rgba(255,255,255,.06);
+  position:relative;
+  cursor:pointer;
+}
+.switch::after{
+  content:"";
+  position:absolute;
+  top:3px;
+  left:3px;
+  width:22px;
+  height:22px;
+  border-radius:999px;
+  background:rgba(255,255,255,.85);
+  transition:transform .18s ease;
+}
