+  display:flex;
+  align-items:flex-start;
+  justify-content:space-between;
+  gap:14px;
+  padding:14px;
+  border-radius:18px;
+  border:1px solid rgba(255,255,255,.12);
+  background:rgba(255,255,255,.03);
+  margin-top:12px;
+}
+.tog strong{color:var(--text)}
+.switch{
+  width:46px;
+  height:28px;
+  border-radius:999px;
+  border:1px solid rgba(255,255,255,.16);
+  background:rgba(255,255,255,.06);
+  position:relative;
+  cursor:pointer;
+}
+.switch::after{
+  content:"";
+  position:absolute;
+  top:3px;
+  left:3px;
+  width:22px;
+  height:22px;
+  border-radius:999px;
+  background:rgba(255,255,255,.85);
+  transition:transform .18s ease;
+}
+.switch[aria-checked="true"]{background:rgba(46,176,255,.24); border-color:rgba(46,176,255,.35)}
+.switch[aria-checked="true"]::after{transform:translateX(18px); background:#EAF6FF}
+.modal__actions{display:flex; justify-content:flex-end; gap:10px; flex-wrap:wrap; margin-top:16px}
+
+/* Mobile nav */
+.mobile-panel{display:none}
